// Java Backend – extended bank (V1.1). Topics reflect 2025–2026 interview trends:
// Java 17/21+, JMM, Spring Boot 3, JPA, microservices, design patterns, reactive, security.
import { kp, Q } from './kp.js';

export const JAVA_MORE = [
  // ---------- Core Java & OOP ----------
  Q('java-101', 'Core Java & OOP', 'E', 'concept', 'What is the difference between == and equals() in Java?',
    [kp('== compares references for objects', 'reference*', 'same object', 'memory address'), kp('equals compares logical content', 'content', 'logical equality', 'value'), kp('Primitives compare values with ==', 'primitive*'), kp('String pool and Integer cache pitfalls', 'string pool', 'integer cache', '127')],
    'For primitives, == compares values. For objects, == compares references, so it is true only when both variables point to the same object in memory. equals compares logical content, and classes like String override it to compare the value. A common pitfall is comparing strings with ==, which may work for literals because of the string pool but fails for new strings, and Integer values between minus 128 and 127 come from the Integer cache so == looks correct only in that range.',
    'Why does new Integer(127) == new Integer(127) return false?'),
  Q('java-102', 'Core Java & OOP', 'EM', 'concept', 'Is Java pass-by-value or pass-by-reference? Explain with an example.',
    [kp('Java is always pass-by-value', 'pass by value', 'always'), kp('Object references are copied', 'copy of the reference', 'reference is copied', 'copy'), kp('Mutating the object is visible to caller', 'mutat*', 'modify the object', 'visible'), kp('Reassigning the parameter does not affect caller', 'reassign*', 'does not affect')],
    'Java is always pass by value. For primitives the value itself is copied. For objects, the value that is passed is the reference, so the method gets a copy of the reference that points to the same object. If the method mutates the object, for example adds to a list, the change is visible to the caller. But if the method reassigns the parameter to a new object, that does not affect the caller variable, which still points to the original object.',
    'How would you write a swap method for two Integer variables, and why does it not work?'),
  Q('java-103', 'Core Java & OOP', 'EM', 'concept', 'What is the difference between static and instance members, and when are static blocks executed?',
    [kp('Static belongs to the class', 'belongs to the class', 'class level', 'shared'), kp('Instance members belong to each object', 'each object', 'per object', 'instance'), kp('Static blocks run once at class loading', 'class load*', 'once'), kp('Static methods cannot access instance state directly', 'cannot access', 'this')],
    'Static fields and methods belong to the class, so there is one shared copy regardless of how many objects exist, while instance members belong to each object. Static methods cannot access instance fields or use this directly, because there is no object. A static block runs once, when the class is initialised during class loading, typically on first use, and is used to set up static state. Overusing static mutable state hurts testability and thread safety.',
    'In what order are static blocks, instance initialisers and constructors executed?'),
  Q('java-104', 'Core Java & OOP', 'EMS', 'concept', 'How do you design an immutable class in Java?',
    [kp('Make the class final', 'final class', 'class final'), kp('Private final fields', 'private final', 'final fields'), kp('No setters', 'no setter*'), kp('Defensive copies of mutable fields', 'defensive cop*', 'copy'), kp('Records simplify it', 'record*')],
    'I make the class final so it cannot be subclassed, make all fields private final, provide no setters, and initialise everything in the constructor. For mutable fields such as lists or dates, I make defensive copies on the way in and return copies or unmodifiable views on the way out, for example with List.copyOf. Immutable objects are thread safe and make good map keys. In modern Java, records give most of this for free, but you still need defensive copies for mutable components.',
    'Is a record with a List component truly immutable?'),
  Q('java-105', 'Core Java & OOP', 'EM', 'concept', 'What is the difference between method overloading and method overriding?',
    [kp('Overloading: same name, different parameters, compile time', 'overloading', 'different parameter*', 'compile time'), kp('Overriding: subclass redefines with same signature, runtime', 'overriding', 'same signature', 'runtime'), kp('Rules: covariant return, not weaker access, checked exceptions', 'covariant', 'access modifier', 'weaker', 'checked exception*'), kp('@Override annotation', 'override annotation', 'annotation')],
    'Overloading means several methods with the same name but different parameter lists in the same class; the compiler picks one at compile time. Overriding means a subclass provides its own implementation of an inherited method with the same signature, and the JVM picks the implementation at runtime based on the actual object. When overriding, the return type can be covariant, the access modifier cannot be weaker, and you cannot throw broader checked exceptions. Always add the Override annotation so the compiler catches mistakes.',
    'Can you override a static or private method?'),
  Q('java-106', 'Core Java & OOP', 'MS', 'concept', 'How do generics work in Java, and what is type erasure? Explain wildcards and PECS.',
    [kp('Compile-time type safety', 'type safety', 'compile time'), kp('Type erasure removes type info at runtime', 'type erasure', 'erased', 'runtime'), kp('Wildcards: extends and super', 'extends', 'super', 'wildcard*'), kp('PECS: producer extends, consumer super', 'pecs', 'producer extends', 'consumer super')],
    'Generics give compile time type safety and remove casts. They are implemented with type erasure: generic type information is erased at runtime and replaced by bounds or Object, which is why you cannot do new T or instanceof List of String. Wildcards make APIs flexible: a List of question mark extends Number can be read as Numbers, and a List of question mark super Integer can accept Integers. The rule is PECS, producer extends, consumer super, as used in Collections.copy.',
    'Why can you not add an Integer to a List<? extends Number>?'),
  Q('java-107', 'Core Java & OOP', 'MS', 'concept', 'What is the Java Memory Model, and what does happens-before mean?',
    [kp('Defines visibility and ordering between threads', 'visibility', 'ordering', 'reorder*'), kp('Happens-before relationship', 'happens before'), kp('Sources: volatile, synchronized/locks, thread start/join', 'volatile', 'synchronized', 'join', 'thread start'), kp('Without it: stale values and data races', 'stale', 'data race*', 'cache*')],
    'The Java Memory Model defines when a write by one thread is guaranteed to be visible to another, and which reorderings the compiler and CPU may do. The key concept is happens before: if action A happens before action B, B sees the effects of A. Happens before edges come from releasing and acquiring the same lock with synchronized, writing and then reading a volatile field, Thread start and join, and final field initialisation. Without such an edge you have a data race and threads can see stale cached values or partially constructed objects.',
    'Why is safe publication of objects important, and how do you achieve it?'),
  Q('java-108', 'Core Java & OOP', 'E', 'concept', 'What are access modifiers in Java and what does each allow?',
    [kp('public: everywhere', 'public', 'everywhere'), kp('protected: package plus subclasses', 'protected', 'subclass*'), kp('default/package-private', 'package private', 'default'), kp('private: only inside the class', 'private', 'same class')],
    'Java has four access levels. public members are accessible everywhere. protected members are accessible within the same package and from subclasses, even in other packages. With no modifier, called default or package private, access is limited to the same package. private members are accessible only inside the same class. Good encapsulation means using the most restrictive level possible, typically private fields with public methods, and using modules since Java 9 to control which packages are exported.',
    'Can a top-level class be private or protected?'),
  Q('java-109', 'Core Java & OOP', 'EM', 'concept', 'How do Comparable and Comparator differ? How do you sort a list of employees by salary then name?',
    [kp('Comparable defines natural ordering (compareTo)', 'comparable', 'compareto', 'natural order*'), kp('Comparator defines external/custom ordering (compare)', 'comparator', 'custom order*', 'compare'), kp('Comparator.comparing and thenComparing', 'comparing', 'thencomparing'), kp('Consistency with equals', 'consistent with equals', 'equals')],
    'Comparable is implemented by the class itself with compareTo and defines its natural ordering, for example String or LocalDate. Comparator is a separate object with a compare method, so you can define many custom orderings without changing the class. To sort employees by salary then name I write list.sort with Comparator.comparing by salary, thenComparing by name, and reversed if needed. Ideally the ordering should be consistent with equals, otherwise sorted sets like TreeSet can drop elements that compare as zero.',
    'What happens if compareTo returns 0 for two unequal objects in a TreeSet?'),

  // ---------- Collections ----------
  Q('java-110', 'Collections', 'EM', 'concept', 'What are fail-fast and fail-safe iterators?',
    [kp('Fail-fast throws ConcurrentModificationException', 'fail fast', 'concurrentmodificationexception'), kp('modCount detection', 'modcount', 'modification count'), kp('Fail-safe/weakly consistent work on a copy or snapshot', 'fail safe', 'weakly consistent', 'snapshot', 'copy'), kp('Examples: ArrayList vs CopyOnWriteArrayList / ConcurrentHashMap', 'copyonwritearraylist', 'concurrenthashmap', 'arraylist')],
    'Fail fast iterators, used by ArrayList and HashMap, track a modCount and throw ConcurrentModificationException if the collection is structurally modified during iteration other than through the iterator remove method. It is a best-effort bug detector, not a thread safety guarantee. Fail safe or weakly consistent iterators, used by CopyOnWriteArrayList and ConcurrentHashMap, do not throw: CopyOnWriteArrayList iterates over a snapshot copy, and ConcurrentHashMap reflects some or none of concurrent changes. To remove while iterating, use Iterator remove or removeIf.',
    'When would you choose CopyOnWriteArrayList?'),
  Q('java-111', 'Collections', 'EM', 'concept', 'Compare HashMap, LinkedHashMap and TreeMap. When do you use each?',
    [kp('HashMap: no order, O(1)', 'hashmap', 'no order', 'unordered'), kp('LinkedHashMap: insertion or access order, LRU', 'linkedhashmap', 'insertion order', 'access order', 'lru'), kp('TreeMap: sorted, red-black tree, O(log n)', 'treemap', 'sorted', 'red black tree', 'log n'), kp('Navigable operations', 'navigablemap', 'floorkey', 'ceilingkey', 'range')],
    'HashMap gives average O 1 lookups with no order guarantee. LinkedHashMap keeps a linked list through the entries, so it preserves insertion order, or access order when configured, which makes it easy to build an LRU cache by overriding removeEldestEntry. TreeMap is a red black tree that keeps keys sorted, with O log n operations, and implements NavigableMap, so it supports floorKey, ceilingKey and range views, which is useful for time ranges or leaderboards. I default to HashMap and choose the others only when ordering matters.',
    'How would you implement an LRU cache with LinkedHashMap?'),
  Q('java-112', 'Collections', 'EMS', 'concept', 'What are immutable collections in modern Java, and how do List.of and Collections.unmodifiableList differ?',
    [kp('List.of creates truly immutable collections', 'list of', 'immutable'), kp('unmodifiableList is a read-only view', 'unmodifiablelist', 'view', 'read only'), kp('Underlying changes show through the view', 'underlying', 'backing', 'reflect*'), kp('List.of rejects nulls', 'null*')],
    'List.of, Set.of and Map.of, added in Java 9, create truly immutable collections: any modification throws UnsupportedOperationException, and they reject null elements. Collections.unmodifiableList only wraps an existing list in a read only view, so if someone still holds the underlying backing list and changes it, the changes reflect through the view. List.copyOf creates an immutable copy, and Stream toList returns an unmodifiable list. I use immutable collections for return values and constants to avoid accidental mutation.',
    'Why might Set.of throw an exception at creation time?'),

  // ---------- Concurrency ----------
  Q('java-113', 'Concurrency', 'MS', 'concept', 'How does ReentrantLock differ from synchronized?',
    [kp('Both are reentrant mutual exclusion', 'reentrant', 'mutual exclusion'), kp('tryLock and timeouts', 'trylock', 'timeout'), kp('Interruptible and fairness options', 'interruptib*', 'fair*'), kp('Must unlock in finally', 'finally', 'unlock'), kp('Conditions / ReadWriteLock', 'condition*', 'readwritelock', 'read write lock')],
    'Both provide reentrant mutual exclusion and the same memory visibility guarantees. synchronized is simpler and the lock is released automatically. ReentrantLock adds tryLock with a timeout, lockInterruptibly so a waiting thread can be interrupted, an optional fair mode, and multiple Condition objects instead of a single wait and notify. The cost is that you must call unlock in a finally block. For read-heavy data, ReentrantReadWriteLock or StampedLock allow concurrent readers.',
    'When would a StampedLock optimistic read help?'),
  Q('java-114', 'Concurrency', 'MS', 'concept', 'Explain CountDownLatch, CyclicBarrier and Semaphore with use cases.',
    [kp('CountDownLatch: wait until N events, one-shot', 'countdownlatch', 'one shot', 'countdown'), kp('CyclicBarrier: threads wait for each other, reusable', 'cyclicbarrier', 'reusable', 'wait for each other'), kp('Semaphore: limit concurrent access with permits', 'semaphore', 'permit*'), kp('Concrete use cases', 'connection*', 'startup', 'rate', 'parallel')],
    'A CountDownLatch lets one or more threads wait until a count reaches zero, for example the main thread waits for five services to finish startup; it is one shot and cannot be reset. A CyclicBarrier makes a fixed number of threads wait for each other at a barrier point before continuing, and it is reusable, which suits parallel phases of a computation. A Semaphore holds a number of permits and limits how many threads access a resource at once, for example limiting concurrent calls to a downstream API or connection usage. Phaser generalises latch and barrier.',
    'How would you use a Semaphore together with virtual threads?'),
  Q('java-115', 'Concurrency', 'MS', 'concept', 'How do you size and configure a ThreadPoolExecutor? What happens when the queue is full?',
    [kp('Core and max pool size', 'core pool', 'maximum pool', 'max pool'), kp('Bounded queue', 'bounded queue', 'queue'), kp('Rejection policies', 'rejection polic*', 'callerrunspolicy', 'abortpolicy'), kp('CPU-bound vs IO-bound sizing', 'cpu bound', 'number of cores', 'io bound', 'i o bound')],
    'A ThreadPoolExecutor keeps core pool threads alive, queues tasks when they are busy, and creates threads up to the maximum pool size only when the queue is full. I always use a bounded queue so memory cannot grow without limit. When both the queue and max threads are exhausted, the rejection policy applies: AbortPolicy throws, CallerRunsPolicy runs the task on the caller thread which creates natural back pressure, and discard policies drop work. For CPU bound tasks I size around the number of cores; for IO bound tasks larger, based on wait time, or I use virtual threads.',
    'Why can a pool with a large unbounded queue never grow beyond its core size?'),
  Q('java-116', 'Concurrency', 'SL', 'concept', 'What is ThreadLocal, and what are its risks in thread pools and with virtual threads?',
    [kp('Per-thread value', 'per thread', 'each thread', 'own copy'), kp('Use cases: request context, MDC, formatters', 'mdc', 'request context', 'simpledateformat', 'context'), kp('Memory leaks / stale data in pools: call remove', 'leak*', 'remove', 'stale'), kp('Scoped values as modern alternative', 'scoped value*', 'scopedvalue')],
    'ThreadLocal gives each thread its own copy of a value, which is used for request context such as the security context, the logging MDC, or non thread safe objects like SimpleDateFormat. The risk is that pool threads live for a long time, so if you do not call remove in a finally block, values leak memory and stale data from one request can appear in the next. With millions of virtual threads, heavy ThreadLocal use also costs memory. Java 21 previews ScopedValue as an immutable, bounded alternative for passing context.',
    'How does the MDC context get propagated to async threads?'),
  Q('java-117', 'Concurrency', 'SL', 'concept', 'What is structured concurrency in modern Java and why does it matter?',
    [kp('Treat related tasks as a unit', 'unit', 'related task*', 'group'), kp('StructuredTaskScope', 'structuredtaskscope'), kp('Cancellation and error propagation', 'cancel*', 'error propagation', 'fail*'), kp('Works with virtual threads', 'virtual thread*'), kp('Preview status', 'preview')],
    'Structured concurrency treats a group of related tasks running in different threads as a single unit of work whose lifetime is bounded by a code block. With StructuredTaskScope you fork subtasks, for example fetching a user and their orders in parallel, then join; if one fails, the scope can cancel the others and propagate the error, and no thread outlives the block. It makes concurrent code as readable as sequential code and fits naturally with virtual threads. It has been a preview API since Java 21, so it needs the enable preview flag.',
    'How is this different from using CompletableFuture.allOf?'),

  // ---------- JVM ----------
  Q('java-118', 'JVM & Performance', 'MS', 'concept', 'How does class loading work in the JVM? Explain the delegation model.',
    [kp('Loading, linking, initialisation phases', 'loading', 'linking', 'initiali*'), kp('Bootstrap, platform, application class loaders', 'bootstrap', 'platform class loader', 'application class loader', 'system class loader'), kp('Parent delegation', 'parent', 'delegat*'), kp('Problems: ClassNotFoundException, NoClassDefFoundError, conflicts', 'classnotfoundexception', 'noclassdeffounderror', 'conflict*')],
    'Class loading has three phases: loading the bytecode, linking which verifies, prepares and resolves it, and initialisation which runs static initialisers. There is a hierarchy of loaders: the bootstrap loader for core classes, the platform class loader, and the application class loader for the classpath. They use parent delegation: a loader first asks its parent, so core classes cannot be replaced. Typical problems are ClassNotFoundException when a class is missing, NoClassDefFoundError when it was present at compile time but fails at runtime, and version conflicts between jars.',
    'How do application servers or plugins break the parent-first rule, and why?'),
  Q('java-119', 'JVM & Performance', 'SL', 'concept', 'How does the JIT compiler optimise code, and what do warm-up and GraalVM native images change?',
    [kp('Interpreter then JIT for hot code', 'interpret*', 'hot', 'jit'), kp('Tiered compilation C1/C2', 'tiered', 'c1', 'c2'), kp('Optimisations: inlining, escape analysis', 'inlining', 'escape analysis'), kp('Warm-up latency', 'warm up', 'warmup'), kp('Native image / AOT, CRaC', 'native image', 'graalvm', 'aot', 'ahead of time', 'crac')],
    'The JVM starts by interpreting bytecode and profiles which methods are hot. Tiered compilation first compiles hot code with C1 quickly, then recompiles the hottest code with C2 using profile data, applying inlining, escape analysis which can remove allocations, loop unrolling and speculative optimisations. That is why Java services need warm up before reaching peak performance. GraalVM native image compiles ahead of time into a native binary with millisecond startup and lower memory, useful for serverless, at the cost of build time and reflection configuration. CRaC and Leyden-style AOT caches are other ways to cut startup.',
    'What would make you choose a native image for a Spring Boot service?'),
  Q('java-120', 'JVM & Performance', 'MS', 'scenario', 'A Java service shows 100 percent CPU in production. How do you find the cause?',
    [kp('Identify the busy threads (top -H)', 'top', 'thread id*', 'busy thread*'), kp('Thread dumps (jstack/jcmd) and map thread ids', 'thread dump*', 'jstack', 'jcmd', 'hex'), kp('Profile with async-profiler / JFR flame graphs', 'async profiler', 'jfr', 'flame graph*', 'profil*'), kp('Check GC activity', 'gc', 'garbage collect*'), kp('Common causes: infinite loop, regex, hot spin', 'infinite loop', 'regex', 'spin*', 'serializ*')],
    'First I check whether it is GC: if GC logs or jstat show constant collections, it is memory pressure, not code. Otherwise I find the busy threads with top with the H flag, convert the thread id to hex, and take a few thread dumps with jstack or jcmd a few seconds apart to see which stack keeps appearing. Better still, I record a profile with async profiler or JFR and read the flame graph. Common causes are an infinite loop, catastrophic regex backtracking, a spin wait, heavy JSON serialization, or logging in a hot path.',
    'How would you do this safely inside a Kubernetes pod without a shell?'),

  // ---------- Java 8+ / modern ----------
  Q('java-121', 'Java 8+ Features', 'EM', 'concept', 'What is the difference between map and flatMap in streams, and how does Collectors.groupingBy work?',
    [kp('map: one-to-one transformation', 'map', 'one to one'), kp('flatMap: flattens nested streams', 'flatmap', 'flatten*'), kp('groupingBy builds a Map by classifier', 'groupingby', 'classifier', 'group'), kp('Downstream collectors: counting, mapping', 'downstream', 'counting', 'summingint', 'mapping')],
    'map transforms each element one to one, so a stream of orders becomes a stream of totals. flatMap maps each element to a stream and then flattens them into one stream, so a stream of orders each with a list of items becomes a single stream of items. Collectors groupingBy takes a classifier function and builds a Map from key to list, and it accepts a downstream collector such as counting, summingInt or mapping, for example counting orders per customer. partitioningBy is the special case with a boolean key.',
    'How would you find the top three customers by total order value using streams?'),
  Q('java-122', 'Java 8+ Features', 'EM', 'concept', 'How does the java.time API improve on Date and Calendar?',
    [kp('Immutable and thread-safe', 'immutable', 'thread safe'), kp('Clear types: LocalDate, LocalDateTime, Instant', 'localdate', 'localdatetime', 'instant'), kp('Time zones: ZonedDateTime, ZoneId', 'zoneddatetime', 'zoneid', 'time zone*'), kp('Duration/Period and DateTimeFormatter', 'duration', 'period', 'datetimeformatter')],
    'The java.time API from Java 8 replaces the mutable, confusing Date and Calendar classes. Its classes are immutable and thread safe, and each type has a clear meaning: LocalDate for a date without time, LocalDateTime without a zone, Instant for a point on the timeline in UTC, and ZonedDateTime with a ZoneId for time zone aware values. Duration and Period represent amounts of time, and DateTimeFormatter is thread safe unlike SimpleDateFormat. In backends I store Instant or UTC timestamps and convert to the user zone only for display.',
    'How would you inject a Clock to make time-dependent code testable?'),
  Q('java-123', 'Java 8+ Features', 'MS', 'concept', 'What are sequenced collections and other notable features introduced in Java 21?',
    [kp('Sequenced collections: getFirst/getLast/reversed', 'sequenced collection*', 'getfirst', 'getlast', 'reversed'), kp('Record patterns', 'record pattern*'), kp('Pattern matching for switch', 'pattern matching', 'switch'), kp('Virtual threads final', 'virtual thread*'), kp('LTS release', 'lts', 'long term support')],
    'Java 21 is an LTS release, long term support. Sequenced collections add interfaces like SequencedCollection and SequencedMap with getFirst, getLast, addFirst and reversed, giving a uniform API for ordered collections such as List, Deque and LinkedHashMap. Record patterns let you deconstruct records directly in instanceof and switch, and pattern matching for switch became final with exhaustiveness checks over sealed types. Virtual threads became final, and generational ZGC arrived. Java 25 is the next LTS after 21.',
    'How would you refactor a chain of if-instanceof checks using Java 21 features?'),

  // ---------- Spring ----------
  Q('java-124', 'Spring Boot', 'EM', 'concept', 'Explain the lifecycle of a Spring bean.',
    [kp('Instantiation and dependency injection', 'instantiat*', 'dependency injection', 'inject*'), kp('Aware interfaces and BeanPostProcessor', 'beanpostprocessor', 'aware'), kp('Initialisation callbacks: @PostConstruct, afterPropertiesSet', 'postconstruct', 'afterpropertiesset', 'init method'), kp('Destruction callbacks: @PreDestroy', 'predestroy', 'destroy*'), kp('Proxies created during post-processing', 'proxy', 'proxies', 'aop')],
    'The container first instantiates the bean, then performs dependency injection of its properties and constructor arguments. Aware interfaces like ApplicationContextAware are called, then BeanPostProcessor before-initialisation hooks run, then initialisation callbacks such as PostConstruct, afterPropertiesSet or a custom init method. Next, BeanPostProcessor after-initialisation hooks run, which is where AOP proxies are created for features like Transactional. The bean is then ready. On shutdown, PreDestroy and destroy methods are called for singletons; prototype beans are not destroyed by the container.',
    'Why might @Transactional not work on a bean created with new?'),
  Q('java-125', 'Spring Boot', 'EM', 'concept', 'How do you manage configuration and profiles in Spring Boot?',
    [kp('application.yml/properties and profiles', 'application yml', 'application properties', 'profile*'), kp('@ConfigurationProperties type-safe binding', 'configurationproperties', 'type safe'), kp('Externalised config: environment variables, config server', 'environment variable*', 'config server', 'externali*'), kp('Property precedence', 'precedence', 'override*'), kp('Secrets not in config files', 'secret*', 'vault')],
    'Configuration lives in application yml or application properties, with profile specific files such as application-prod yml activated by spring.profiles.active. I bind related settings with ConfigurationProperties classes for type safe, validated config instead of scattered Value annotations. Spring Boot externalises configuration with a defined precedence: command line arguments and environment variables override files, which is how containers and Kubernetes ConfigMaps inject values. Secrets do not belong in config files; they come from Vault, a cloud secret manager or Kubernetes secrets, and Spring Cloud Config Server can centralise config.',
    'How would you reload configuration without restarting the service?'),
  Q('java-126', 'Spring Boot', 'EM', 'concept', 'How do you handle exceptions and validation globally in a Spring Boot REST API?',
    [kp('@RestControllerAdvice with @ExceptionHandler', 'restcontrolleradvice', 'controlleradvice', 'exceptionhandler'), kp('Bean Validation with @Valid', 'valid', 'bean validation', 'notnull', 'notblank'), kp('Consistent error body / ProblemDetail', 'problemdetail', 'problem detail*', 'error response'), kp('Correct status codes and no stack traces', 'status code*', '400', 'stack trace*')],
    'I use a RestControllerAdvice class with ExceptionHandler methods that map exceptions to responses in one place, for example a not-found exception to 404 and validation errors to 400. Request DTOs carry Bean Validation annotations like NotBlank and Size, and controllers use Valid so invalid input fails before business logic. Errors are returned in a consistent error response format; Spring 6 supports RFC 9457 through ProblemDetail. I never leak stack traces to clients, log them server side with a correlation id, and choose correct status codes.',
    'How would you return all field validation errors in one response?'),
  Q('java-127', 'Spring Boot', 'MS', 'concept', 'How does Spring AOP work, and what are its limitations?',
    [kp('Aspects, advice, pointcuts', 'aspect*', 'advice', 'pointcut*'), kp('Proxy-based: JDK dynamic proxy or CGLIB', 'proxy', 'jdk dynamic', 'cglib'), kp('Cross-cutting concerns', 'cross cutting', 'logging', 'transaction*', 'security'), kp('Limitations: self-invocation, final/private methods', 'self invocation', 'final', 'private')],
    'Spring AOP lets you modularise cross cutting concerns like logging, transactions, security and metrics. An aspect contains advice, the code to run, such as before, after or around, and a pointcut that selects which methods it applies to. Spring implements it with runtime proxies: a JDK dynamic proxy when the bean implements an interface, otherwise a CGLIB subclass proxy. Because of proxies, self invocation inside the same class is not intercepted, and final or private methods cannot be advised. For those cases you need AspectJ weaving.',
    'How would you write an around advice that measures method execution time?'),
  Q('java-128', 'Spring Boot', 'MS', 'concept', 'What changed in Spring Boot 3 compared with Spring Boot 2?',
    [kp('Java 17 baseline', 'java 17', 'baseline'), kp('Jakarta EE namespace (javax to jakarta)', 'jakarta'), kp('Observability with Micrometer Observation/Tracing', 'micrometer', 'observation', 'tracing'), kp('GraalVM native image support', 'native image', 'graalvm', 'aot'), kp('ProblemDetail, HTTP interfaces', 'problemdetail', 'http interface*', 'httpexchange')],
    'Spring Boot 3, built on Spring Framework 6, requires a Java 17 baseline and moves from Java EE to the Jakarta EE namespace, so imports change from javax to jakarta, which is the biggest migration effort. Observability was reworked around the Micrometer Observation API with Micrometer Tracing replacing Spring Cloud Sleuth. It has first class GraalVM native image support through AOT processing. It also added ProblemDetail for RFC 9457 errors and declarative HTTP interfaces with HttpExchange. Later 3.x releases added virtual thread support and RestClient.',
    'How would you plan a Boot 2 to Boot 3 migration for twenty services?'),
  Q('java-129', 'Spring Boot', 'MS', 'concept', 'How do you call other services from Spring Boot? Compare RestTemplate, WebClient, RestClient and Feign.',
    [kp('RestTemplate: blocking, maintenance mode', 'resttemplate', 'maintenance'), kp('WebClient: non-blocking reactive', 'webclient', 'non blocking', 'reactive'), kp('RestClient: modern synchronous fluent API', 'restclient', 'fluent'), kp('Feign / HTTP interfaces: declarative', 'feign', 'declarative', 'http interface*'), kp('Timeouts, retries, connection pooling', 'timeout*', 'retr*', 'connection pool*')],
    'RestTemplate is the classic blocking client and is in maintenance mode. WebClient is the non blocking reactive client from WebFlux, good for high concurrency and streaming. RestClient, added in Spring 6.1, offers a modern fluent synchronous API and is my default for blocking code, especially with virtual threads. OpenFeign and Spring HTTP interfaces are declarative: you write an interface and the client is generated. Whatever the client, I configure timeouts, connection pooling, retries with backoff, and a circuit breaker, and propagate trace headers.',
    'What default timeout does a client have if you configure none, and why is that dangerous?'),
  Q('java-130', 'Spring Boot', 'MS', 'concept', 'What does Spring Boot Actuator provide, and how do you secure it?',
    [kp('Health, metrics, info endpoints', 'health', 'metrics', 'info'), kp('Liveness/readiness for Kubernetes', 'liveness', 'readiness'), kp('Prometheus endpoint via Micrometer', 'prometheus', 'micrometer'), kp('Secure: expose minimally, separate port, auth', 'expose', 'management port', 'separate port', 'secur*')],
    'Actuator adds production endpoints: health with details for the database and other dependencies, metrics, info, env, loggers, thread dump and more. It provides liveness and readiness health groups that map directly to Kubernetes probes, and with the Micrometer registry it exposes a prometheus endpoint for scraping. To secure it, I expose only the endpoints needed, put management on a separate port not reachable from the internet, protect sensitive endpoints with Spring Security, and never expose env or heapdump publicly because they leak secrets.',
    'Which health indicators would you include in readiness but not liveness?'),

  // ---------- Spring Data & JPA ----------
  Q('java-131', 'Spring Data & JPA', 'EM', 'concept', 'Explain the JPA entity lifecycle states and the persistence context.',
    [kp('States: transient/new, managed, detached, removed', 'transient', 'managed', 'detached', 'removed'), kp('Persistence context = first-level cache', 'persistence context', 'first level cache'), kp('Dirty checking flushes changes', 'dirty checking', 'flush*'), kp('merge vs persist', 'merge', 'persist')],
    'A new entity created with new is transient, not tracked. After persist, or when loaded, it is managed, which means it lives in the persistence context, a first level cache keyed by id within the transaction. Hibernate performs dirty checking on managed entities and flushes changed fields as SQL at commit, so you do not need to call save. When the context closes the entity becomes detached; merge copies a detached entity state back into a managed one. remove marks it removed, deleted on flush.',
    'Why might calling save inside a loop of 100,000 entities cause memory problems?'),
  Q('java-132', 'Spring Data & JPA', 'MS', 'concept', 'What is the difference between optimistic and pessimistic locking in JPA?',
    [kp('Optimistic: @Version, check at update', 'optimistic', 'version'), kp('OptimisticLockException on conflict, retry', 'optimisticlockexception', 'retry', 'conflict'), kp('Pessimistic: database row locks', 'pessimistic', 'select for update', 'row lock*'), kp('When to use each: contention level', 'contention', 'low contention', 'high contention')],
    'Optimistic locking assumes conflicts are rare. You add a Version column; every update includes where version equals the old value and increments it, and if another transaction changed the row first, zero rows are updated and an OptimisticLockException is thrown, so you retry or tell the user. Pessimistic locking takes a database row lock up front, typically select for update, so others wait. I use optimistic locking for typical web apps with low contention, and pessimistic for short, high contention operations such as decrementing inventory or account balances.',
    'How would you handle an OptimisticLockException in a REST API?'),
  Q('java-133', 'Spring Data & JPA', 'MS', 'concept', 'How do you handle database schema migrations in a Java application?',
    [kp('Flyway or Liquibase', 'flyway', 'liquibase'), kp('Versioned migration scripts in source control', 'versioned', 'source control', 'script*'), kp('Never ddl-auto update in production', 'ddl auto', 'hibernate ddl', 'production'), kp('Backward-compatible expand and contract', 'backward compatible', 'expand and contract', 'zero downtime')],
    'I use Flyway or Liquibase with versioned migration scripts kept in source control and run automatically at startup or in the pipeline, so every environment has the same schema history. I never use Hibernate ddl auto update in production. For zero downtime deployments, changes must be backward compatible using expand and contract: first add the new column or table, deploy code that writes both, backfill data, switch reads, and only in a later release drop the old column. Large table changes run as batched or online migrations.',
    'How would you rename a column used by a running service without downtime?'),

  // ---------- REST, reactive, gRPC ----------
  Q('java-134', 'REST & API Design', 'MS', 'concept', 'When would you choose gRPC or GraphQL over REST?',
    [kp('gRPC: HTTP/2, protobuf, fast internal calls, streaming', 'grpc', 'protobuf', 'http 2', 'streaming'), kp('GraphQL: client-selected fields, one endpoint', 'graphql', 'client select*', 'over fetching', 'single endpoint'), kp('REST: simple, cacheable, public APIs', 'rest', 'cacheable', 'public api*'), kp('Trade-offs: tooling, caching, complexity', 'trade off*', 'complexity', 'tooling')],
    'REST over HTTP and JSON is simple, cacheable and universally understood, so it is my default for public APIs. gRPC uses HTTP 2 and protobuf with generated clients, giving compact, fast, strongly typed calls and bidirectional streaming, so it fits internal service to service traffic. GraphQL exposes a single endpoint where clients select exactly the fields they need, which avoids over fetching for complex UIs and mobile apps, but HTTP caching, authorization per field and N plus 1 resolvers add complexity. The trade off is tooling and team familiarity versus efficiency.',
    'How do you version a gRPC API safely?'),
  Q('java-135', 'REST & API Design', 'SL', 'concept', 'What is reactive programming with Spring WebFlux, and when is it worth it?',
    [kp('Non-blocking, event loop (Netty)', 'non blocking', 'event loop', 'netty'), kp('Mono and Flux (Project Reactor)', 'mono', 'flux', 'reactor'), kp('Backpressure', 'backpressure', 'back pressure'), kp('Never block inside reactive code', 'never block', 'blocking call*', 'block'), kp('Virtual threads as simpler alternative', 'virtual thread*')],
    'WebFlux is Spring non blocking web stack built on Project Reactor, usually running on Netty with a small event loop. You compose Mono for zero or one value and Flux for many, and Reactor supports backpressure so a slow consumer can control the rate. It shines for very high concurrency, streaming and gateways. The cost is a harder programming model, harder debugging, and the rule that you must never block inside reactive code, which rules out JDBC unless you use R2DBC. With Java 21 virtual threads, plain Spring MVC is often enough.',
    'What happens if you call a blocking JDBC query inside a WebFlux handler?'),
  Q('java-136', 'REST & API Design', 'SL', 'design', 'How do you make an API safe against duplicate requests, for example in payments?',
    [kp('Idempotency key header', 'idempotency key'), kp('Store key with result, return same response', 'store', 'same response', 'stored response'), kp('Unique constraint / atomic check', 'unique constraint', 'atomic*', 'lock'), kp('Expiry/TTL of keys', 'ttl', 'expir*'), kp('Handle concurrent in-flight duplicates', 'in flight', 'concurrent', 'in progress')],
    'Clients send an idempotency key header, a unique id per logical operation. The server stores the key atomically, using a unique constraint or an atomic insert in Redis, before processing. If the same key arrives again, it does not process again but returns the same response that was stored after the first request. If a duplicate arrives while the first is still in flight, it returns 409 or waits. Keys have an expiry or TTL, for example 24 hours, and are scoped per client. Downstream calls should also be idempotent.',
    'Where would you store idempotency keys for a service with ten instances?'),

  // ---------- Microservices ----------
  Q('java-137', 'Microservices', 'MS', 'concept', 'What is an API gateway, and what is service discovery?',
    [kp('Gateway: single entry point, routing', 'api gateway', 'single entry point', 'routing'), kp('Cross-cutting at gateway: auth, rate limiting, TLS', 'authentication', 'rate limit*', 'tls'), kp('Service discovery: registry like Eureka/Consul or Kubernetes DNS', 'service discovery', 'eureka', 'consul', 'kubernetes dns', 'registry'), kp('Client-side vs server-side discovery', 'client side', 'server side')],
    'An API gateway, such as Spring Cloud Gateway, Kong or a cloud gateway, is the single entry point for clients: it handles routing to services, authentication, rate limiting, TLS termination and request aggregation, so services do not duplicate these concerns. Service discovery lets services find each other without hard coded addresses: with client side discovery, instances register in a registry like Eureka or Consul and clients look them up; with server side discovery the platform does it, as with Kubernetes DNS and Services, which is the common choice today.',
    'Why is a gateway that contains business logic an anti-pattern?'),
  Q('java-138', 'Microservices', 'SL', 'concept', 'What is CQRS and event sourcing? When would you use them?',
    [kp('CQRS separates command and query models', 'cqrs', 'command', 'query'), kp('Event sourcing stores events as source of truth', 'event sourcing', 'events', 'source of truth', 'append only'), kp('Projections / read models', 'projection*', 'read model*'), kp('Costs: eventual consistency, complexity', 'eventual consistency', 'complexity'), kp('Good fit: audit, complex domains', 'audit*', 'complex domain*')],
    'CQRS, command query responsibility segregation, separates the write model that handles commands from read models optimised for queries, which can be scaled and shaped independently. Event sourcing stores every state change as an append only sequence of events, which becomes the source of truth; current state is rebuilt by replaying events, and projections build read models. Together they give a full audit trail and temporal queries. The cost is eventual consistency between write and read sides, event versioning and much more complexity, so I use them only for complex domains such as ledgers or audit heavy systems.',
    'How do you handle a change to an event schema after years of stored events?'),
  Q('java-139', 'Microservices', 'MS', 'concept', 'What is the transactional outbox pattern, and why is dual-write a problem?',
    [kp('Dual write: DB and broker can diverge', 'dual write', 'inconsisten*', 'diverge'), kp('Outbox table in same local transaction', 'outbox', 'same transaction', 'local transaction'), kp('Relay via polling or CDC (Debezium)', 'debezium', 'cdc', 'change data capture', 'polling'), kp('At-least-once, idempotent consumers', 'at least once', 'idempotent')],
    'A dual write happens when a service writes to its database and then publishes to Kafka; if one succeeds and the other fails, the systems diverge and become inconsistent. The outbox pattern fixes this: the service writes the business change and an event row into an outbox table in the same local transaction. A separate relay then publishes outbox rows to the broker, either by polling or with change data capture using Debezium reading the database log. Delivery is at least once, so consumers must be idempotent.',
    'How would you guarantee ordering of outbox events per aggregate?'),

  // ---------- Security ----------
  Q('java-140', 'Security', 'EM', 'concept', 'What is the difference between authentication and authorization, and how do OAuth 2 and OpenID Connect relate?',
    [kp('Authentication = who you are', 'authentication', 'who you are', 'identity'), kp('Authorization = what you can do', 'authorization', 'permission*', 'what you can'), kp('OAuth 2 is delegated authorization with access tokens', 'oauth', 'access token*', 'delegat*'), kp('OIDC adds identity / ID token', 'openid connect', 'oidc', 'id token')],
    'Authentication verifies who you are, for example with a password, MFA or SSO. Authorization decides what you are allowed to do, such as roles and permissions. OAuth 2 is a framework for delegated authorization: a client obtains an access token from an authorization server to call an API on behalf of a user, using flows such as authorization code with PKCE or client credentials for service to service. OpenID Connect is an identity layer on top of OAuth 2 that adds an ID token with user identity claims, so it handles authentication.',
    'Why should single-page apps use the authorization code flow with PKCE rather than the implicit flow?'),
  Q('java-141', 'Security', 'MS', 'concept', 'How do you protect a Java web application against the OWASP Top 10, such as SQL injection and XSS?',
    [kp('Parameterized queries / prepared statements', 'prepared statement*', 'parameteri*', 'sql injection'), kp('Output encoding / XSS protection', 'xss', 'encod*', 'escap*'), kp('CSRF protection and CORS config', 'csrf', 'cors'), kp('Dependency scanning and patching', 'dependenc*', 'cve', 'patch*'), kp('Secrets and broken access control', 'access control', 'secret*', 'least privilege')],
    'For SQL injection I always use prepared statements or parameterized JPA queries, never string concatenation. For XSS I validate input and rely on output encoding in templates, plus a Content Security Policy. Spring Security provides CSRF protection for cookie based sessions, and I configure CORS narrowly. Broken access control is the top risk, so every endpoint checks authorization on the server, including object ownership. I keep dependencies patched with scanning for known CVEs, store secrets outside code, apply least privilege, and add security headers and rate limiting.',
    'What is an insecure direct object reference, and how do you prevent it?'),
  Q('java-142', 'Security', 'MS', 'concept', 'How should passwords and sensitive data be stored?',
    [kp('Hash passwords with a slow adaptive algorithm', 'bcrypt', 'argon2', 'scrypt', 'pbkdf2'), kp('Salt per password', 'salt*'), kp('Never encrypt or plain-hash passwords (no MD5/SHA)', 'md5', 'sha', 'never'), kp('Encrypt sensitive data at rest with managed keys', 'encrypt*', 'kms', 'key management')],
    'Passwords must never be stored in plain text, encrypted, or hashed with a fast hash like MD5 or SHA 256. I use a slow, adaptive password hashing algorithm such as bcrypt or Argon2, through Spring Security PasswordEncoder, which adds a unique random salt per password and a work factor that can be increased over time. Other sensitive data, like personal data or tokens, is encrypted at rest using keys from a key management service such as AWS KMS or Azure Key Vault, and access is logged and restricted.',
    'How would you upgrade the hashing algorithm for existing users?'),

  // ---------- Design patterns ----------
  Q('java-143', 'Design Patterns', 'EM', 'concept', 'Explain the SOLID principles with examples.',
    [kp('Single responsibility', 'single responsibility'), kp('Open/closed', 'open closed', 'open for extension'), kp('Liskov substitution', 'liskov'), kp('Interface segregation', 'interface segregation'), kp('Dependency inversion', 'dependency inversion', 'abstractions')],
    'Single responsibility: a class should have one reason to change, so a report class should not also send emails. Open closed: code should be open for extension but closed for modification, for example adding a new payment type as a new strategy class. Liskov substitution: subclasses must be usable wherever the parent is expected without breaking behaviour. Interface segregation: prefer small focused interfaces over fat ones. Dependency inversion: high level modules depend on abstractions, not concrete classes, which Spring dependency injection makes natural.',
    'Can you give an example of a Liskov substitution violation?'),
  Q('java-144', 'Design Patterns', 'EM', 'concept', 'How do you implement a thread-safe Singleton in Java, and what are the pitfalls?',
    [kp('Enum singleton', 'enum'), kp('Holder idiom / lazy initialisation', 'holder', 'lazy'), kp('Double-checked locking needs volatile', 'double checked', 'volatile'), kp('Pitfalls: reflection, serialization, testability', 'reflection', 'serializ*', 'testab*', 'global state')],
    'The simplest thread safe singleton is an enum with a single instance, which also handles serialization and reflection attacks. For lazy initialisation I use the holder idiom: a private static nested class holds the instance, and the JVM class initialisation guarantees thread safety. Double checked locking also works but only if the field is volatile. Pitfalls include breaking it via reflection or serialization, and hidden global state that hurts testability. In Spring applications I simply use singleton scoped beans instead.',
    'Why is the Spring singleton scope not the same as the GoF Singleton?'),
  Q('java-145', 'Design Patterns', 'MS', 'concept', 'Which design patterns do you use most in backend code? Explain Strategy, Factory, Builder and Observer.',
    [kp('Strategy: interchangeable algorithms', 'strategy'), kp('Factory: encapsulate object creation', 'factory'), kp('Builder: readable construction of complex objects', 'builder'), kp('Observer / events', 'observer', 'event*', 'listener*'), kp('Real usage examples', 'payment', 'spring', 'example')],
    'Strategy encapsulates interchangeable algorithms behind an interface; for example each payment method implements a PaymentStrategy and Spring injects a map of them, avoiding big switch statements. Factory encapsulates object creation so callers do not depend on concrete classes. Builder constructs complex objects with many optional fields readably, like HTTP requests or Lombok builders. Observer lets components react to events without tight coupling, which Spring supports with ApplicationEventPublisher and EventListener, and at system scale it becomes publish subscribe with Kafka.',
    'Which pattern does Spring use for JdbcTemplate, and why?'),
  Q('java-146', 'Design Patterns', 'SL', 'concept', 'What is hexagonal architecture (ports and adapters), and how does it compare with layered architecture?',
    [kp('Domain at the centre, independent of frameworks', 'domain', 'centre', 'center', 'framework*'), kp('Ports are interfaces, adapters implement them', 'port*', 'adapter*'), kp('Layered: controller-service-repository', 'layered', 'controller', 'repository'), kp('Benefits: testability, swappable infrastructure', 'testab*', 'swap*', 'replace')],
    'In a classic layered architecture, controller calls service calls repository, and the business logic often ends up depending on the database and framework. Hexagonal architecture, or ports and adapters, puts the domain at the centre with no dependency on frameworks. The domain defines ports, which are interfaces for what it needs or offers, and adapters implement them: a REST controller adapter, a JPA adapter, a Kafka adapter. This makes the core easy to unit test and lets you swap infrastructure, at the cost of more interfaces and mapping code.',
    'How would you enforce these boundaries in a codebase, for example with ArchUnit?'),

  // ---------- Testing ----------
  Q('java-147', 'Testing', 'MS', 'concept', 'What is the difference between mocks, stubs and spies, and when does mocking go too far?',
    [kp('Stub returns canned data', 'stub*', 'canned'), kp('Mock verifies interactions', 'mock*', 'verif*', 'interaction*'), kp('Spy wraps a real object', 'spy', 'real object', 'partial'), kp('Over-mocking: brittle tests coupled to implementation', 'brittle', 'implementation detail*', 'over mock*')],
    'A stub returns canned data so the code under test can run. A mock also records calls so you can verify interactions, for example that an email was sent once. A spy wraps a real object, calling real methods except those you stub, which is a partial mock. Mocking goes too far when tests mock everything, including value objects and internal collaborators: they become brittle, break on every refactor, and test implementation details rather than behaviour. I mock only external boundaries and prefer real objects or Testcontainers elsewhere.',
    'How would you test code that calls LocalDateTime.now()?'),
  Q('java-148', 'Testing', 'SL', 'concept', 'How do you test microservice integrations without a full end-to-end environment?',
    [kp('Consumer-driven contract tests (Pact / Spring Cloud Contract)', 'contract test*', 'pact', 'spring cloud contract'), kp('Testcontainers for real dependencies', 'testcontainers'), kp('WireMock for HTTP stubs', 'wiremock'), kp('Few end-to-end smoke tests', 'end to end', 'smoke test*')],
    'I rely on consumer driven contract tests with Pact or Spring Cloud Contract: the consumer publishes its expectations, and the provider pipeline verifies them, so breaking API changes are caught before deployment without a shared environment. Each service runs integration tests with Testcontainers for its real database, Kafka and Redis, and uses WireMock to stub HTTP dependencies, including error and timeout cases. Then only a small number of end to end smoke tests run against staging after deployment, because large end to end suites are slow and flaky.',
    'Who owns a contract when the consumer and provider teams disagree?'),

  // ---------- System design ----------
  Q('java-149', 'System Design', 'SL', 'design', 'Design a notification service that sends email, SMS and push notifications at scale.',
    [kp('API accepts requests and queues them', 'api', 'queue', 'kafka'), kp('Channel-specific workers/providers', 'worker*', 'provider*', 'channel*'), kp('User preferences and templates', 'preference*', 'template*'), kp('Retries, DLQ, idempotency', 'retr*', 'dead letter', 'dlq', 'idempoten*'), kp('Rate limiting and priorities', 'rate limit*', 'priorit*')],
    'Clients call an API that validates the request, applies user preferences such as opt-outs and quiet hours, renders templates, and publishes a message to a queue, for example Kafka topics per channel and priority, so callers are not blocked. Channel specific workers consume and call external providers such as an email service, an SMS gateway and Firebase or APNs for push, with provider failover. Sends are idempotent using a notification id, failures use retries with exponential backoff and finally a dead letter queue. Rate limiting protects providers and users, priorities keep OTPs fast, and delivery status is tracked for analytics.',
    'How do you ensure an OTP is never delayed behind a marketing campaign?'),
  Q('java-150', 'System Design', 'SL', 'design', 'How would you design a scalable e-commerce order service that must not oversell inventory?',
    [kp('Inventory reservation with atomic update / locking', 'reserv*', 'atomic*', 'lock*', 'optimistic'), kp('Saga across order, payment, inventory', 'saga', 'compensat*'), kp('Idempotency for retries', 'idempoten*'), kp('Events via Kafka/outbox', 'kafka', 'outbox', 'event*'), kp('Scaling hot items: caching, sharding, queueing', 'cach*', 'shard*', 'hot item*', 'flash sale')],
    'The order service creates an order in pending state, then reserves stock. To avoid overselling, the reservation is an atomic conditional update, for example update stock set quantity minus one where quantity is at least one, or optimistic locking with a version, so concurrent buyers cannot both take the last item. Payment and inventory are coordinated with a saga: if payment fails, a compensating step releases the reservation; reservations also expire. Events flow through Kafka using the outbox pattern, and every step is idempotent. For flash sales on hot items, I pre-allocate stock in Redis, queue requests, and shard by product.',
    'How would the design change for a flash sale of 1,000 units with a million users?'),

  // ---------- Troubleshooting ----------
  Q('java-151', 'Troubleshooting', 'MS', 'scenario', 'Users report intermittent 500 errors from one microservice. How do you investigate?',
    [kp('Scope via metrics, error rate by instance/endpoint', 'metrics', 'error rate', 'instance', 'endpoint'), kp('Logs with correlation id and stack traces', 'logs', 'correlation id', 'stack trace*'), kp('Traces to find failing dependency', 'trac*', 'downstream', 'dependenc*'), kp('Check resources: pools, timeouts, memory', 'connection pool', 'timeout*', 'memory', 'thread pool'), kp('Reproduce and fix, add alert/test', 'reproduc*', 'alert*', 'test')],
    'First I scope the problem with metrics: the error rate by instance, endpoint and version, and whether it correlates with traffic peaks or a deployment. Then I search logs by correlation id to find the stack traces behind the 500s, and use distributed traces to see whether a downstream dependency is failing or timing out. Intermittent errors are often resource exhaustion, so I check connection pool and thread pool saturation, timeouts, memory and GC, and one bad instance. Once I can reproduce it, I fix it, add a test, and add an alert so it is caught earlier.',
    'Errors only happen on one of five pods. What does that suggest?'),
];
